// animation-scale.js
// More information about curves can be found at: 
// http://developer.playcanvas.com/en/user-manual/scripting/script-attributes/
// http://developer.playcanvas.com/en/api/pc.Curve.html

var AnimateCurve = pc.createScript('animateCurve');

// Example of creating curve attribute with as single curve
AnimateCurve.attributes.add("offsetCurve", {type: "curve", title: "Offset Curve"});
AnimateCurve.attributes.add("duration", {type: "number", default: 1, title: "Duration (secs)"});


// initialize code called once per entity
AnimateCurve.prototype.initialize = function() {
    // Keep track of the original scale of the entity
    this.startScale = this.entity.getLocalScale().clone();
    
    // Keep track of the current scale
    this.scale = new pc.Vec3();
    
    this.time = 0;
};


// update code called every frame
AnimateCurve.prototype.update = function(dt) {
    // Loop the animation forever
    this.time += dt;
    if (this.time > this.duration) {
        this.time -= this.duration;
    }
    
    // Calculate how far in time we are for the animation
    var percent = this.time / this.duration;
       
    // Get curve values using current time relative to duration (percent)
    var curveValue = this.offsetCurve.value(percent);
    
    // Create our new scale from the startScale and offset from the curve value
    this.scale.copy(this.startScale);
    this.scale.x += curveValue;
    this.scale.y += curveValue;
    this.scale.z += curveValue;
    
    this.entity.setLocalScale(this.scale);
};


// MovingPlatform.js
var MovingPlatform = pc.createScript('movingPlatform');

MovingPlatform.attributes.add('minOffset', {
    type: 'vec3'
});

MovingPlatform.attributes.add('maxOffset', {
    type: 'vec3'
});

MovingPlatform.attributes.add("moveCurve", {
    type: "curve"
});

MovingPlatform.attributes.add("speed", {
    type: "number"
});

MovingPlatform.attributes.add("delay", {
    type: "number"
});

const tempVec3s = [new pc.Vec3(), new pc.Vec3(), new pc.Vec3()];

MovingPlatform.prototype.initialize = function() {
    this.startLocalPosition = this.entity.getLocalPosition().clone();
    this.delayTimer = 0;
    this.setAnimationTime(0);
};

MovingPlatform.prototype.update = function(dt) {
    if ((this.delayTimer += dt) < this.delay) {
        return;
    }

    this.setAnimationTime(this.time + dt * this.speed);
};

MovingPlatform.prototype.setAnimationTime = function(time) {
    if ((time %= 1) === this.time) {
        return;
    }

    this.time = time;
    this.sampleAnimationFrame();
};

MovingPlatform.prototype.sampleAnimationFrame = function() {
    const curveValue = this.moveCurve.value(this.time);
    const fromLocal = tempVec3s[0].add2(this.startLocalPosition, this.minOffset);
    const toLocal   = tempVec3s[1].add2(this.startLocalPosition, this.maxOffset);
    const newLocal  = tempVec3s[2].lerp(fromLocal, toLocal, curveValue);
    this.entity.setLocalPosition(newLocal);
};


// GSOTLoadingScreen.js
// More information on creating custom loading screens can be found here
// http://developer.playcanvas.com/en/user-manual/designer/loading-screen/

pc.script.createLoadingScreen(function (app) {
    var showSplash = function () {
        // splash wrapper
        var wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';
        document.body.appendChild(wrapper);

        // splash
        var splash = document.createElement('div');
        splash.id = 'application-splash';
        wrapper.appendChild(splash);
        splash.style.display = 'none';
        
        var container = document.createElement('div');
        container.id = 'progress-bar-container';
        splash.appendChild(container);

        var bar = document.createElement('div');
        bar.id = 'progress-bar';
        container.appendChild(bar);

    };

    var hideSplash = function () {
        var splash = document.getElementById('application-splash-wrapper');
        splash.parentElement.removeChild(splash);
    };

    var setProgress = function (value) {
        var bar = document.getElementById('progress-bar');
        if(bar) {
            value = Math.min(1, Math.max(0, value));
            bar.style.width = value * 100 + '%';
        }
    };

    var createCss = function () {
        var css = [
            'body {',
            '    background-color: #283538;',
            '}',

            '#application-splash-wrapper {',
            '    position: absolute;',
            '    top: 0;',
            '    left: 0;',
            '    height: 100%;',
            '    width: 100%;',
            '    background-color: #283538;',
            '}',

            '#application-splash {',
            '    position: absolute;',
            '    top: calc(50% - 132px);',
            '    width: 264px;',
            '    left: calc(50% - 132px);',
            '}',

            '#application-splash img {',
            '    width: 100%;',
            '}',

            '#progress-bar-container {',
            '    margin: 20px auto 0 auto;',
            '    height: 2px;',
            '    width: 100%;',
            '    background-color: #1d292c;',
            '}',

            '#progress-bar {',
            '    width: 0%;',
            '    height: 100%;',
            '    background-color: #f60;',
            '}',
            '@media (max-width: 480px) {',
            '    #application-splash {',
            '        width: 170px;',
            '        left: calc(50% - 85px);',
            '    }',
            '}'
        ].join("\n");

        var style = document.createElement('style');
        style.type = 'text/css';
        if (style.styleSheet) {
          style.styleSheet.cssText = css;
        } else {
          style.appendChild(document.createTextNode(css));
        }

        document.head.appendChild(style);
    };


    createCss();

    showSplash();
    
    // Use an image from the assets in the project via the asset registry
    // More information: http://developer.playcanvas.com/en/api/pc.AssetRegistry.html
    app.on('preload:start', function() {
        var splash = document.getElementById('application-splash');
        
        var logoAsset = app.assets.find('GSOTLoadingScreen.');
        
        if (logoAsset) {
            var logo = document.createElement('img');    
            logo.src = logoAsset.getFileUrl();

            // Insert DOM before the progress bar
            if (splash.childNodes.length > 0) {
                splash.insertBefore(logo, splash.childNodes[0]);
            } else {
                splash.appendChild(logo);
            }
            
            logo.onload = function () {
                splash.style.display = 'block';
            };
        }
    });
        
    app.on('preload:end', function () {
        app.off('preload:progress');
    });
    app.on('preload:progress', setProgress);
    app.on('start', hideSplash);
});

