// entity-rotator.js
const EntityRotator = pc.createScript('EntityRotator');
const _tempVec3 = new pc.Vec3();
const _tempQuat = new pc.Quat();

EntityRotator.prototype.initialize = function() {
    const rotation = this.entity.getRotation();
    this._rotationEuler = rotation.getEulerAngles();
};

EntityRotator.prototype.update = function(dt) {
    const rotationEuler = this._rotationEuler;
    _tempVec3.copy(this.degreesPerSecond);
    _tempVec3.mulScalar(dt);
    rotationEuler.add(_tempVec3);
    rotationEuler.x %= 360;
    rotationEuler.y %= 360;
    rotationEuler.z %= 360;
    
    _tempQuat.setFromEulerAngles(rotationEuler.x, rotationEuler.y, rotationEuler.z);
    this.entity.setRotation(_tempQuat);
};


EntityRotator.attributes.add("degreesPerSecond", {
    type: "vec3"
});

// input-tutorial-box.js
class InputTutorialBox extends pc.ScriptType {
    initialize() {
        this.desktopRoot.enabled = pc.platform.desktop;
        this.mobileRoot.enabled = pc.platform.mobile;
    }
}

pc.registerScript(InputTutorialBox, "InputTutorialBox");

InputTutorialBox.attributes.add("desktopRoot", {
    type: "entity"
});

InputTutorialBox.attributes.add("mobileRoot", {
    type: "entity"
});

// christmas-toggle.js
class ChristmasToggle extends pc.ScriptType {
    initialize() {
        const currentMonth = new Date().getMonth();
        const isChristmasTime = currentMonth === 10 || currentMonth === 11;
        const entities = this.entities;
        for(let i = 0; i < entities.length; i++) {
            const entity = entities[i];
            entity.enabled = isChristmasTime;
        }

        const outOfSeasonEntities = this.outOfSeasonEntities;
        for(let i = 0; i < outOfSeasonEntities.length; i++) {
            const entity = outOfSeasonEntities[i];
            entity.enabled = !isChristmasTime;
        }
    }
}

pc.registerScript(ChristmasToggle, ChristmasToggle.name);
ChristmasToggle.attributes.add("entities", {
    type: "entity",
    array: true
});

ChristmasToggle.attributes.add("outOfSeasonEntities", {
    type: "entity",
    array: true
});

// seasonal-toggle.js
class SeasonalToggle extends pc.ScriptType {
    initialize() {
        const isSeasonActive = this.isSeasonActive();
        this.setEntitiesEnabled(this.seasonalEntities, isSeasonActive);
        this.setEntitiesEnabled(this.nonSeasonalEntities, !isSeasonActive);
    }

    setEntitiesEnabled(entities, enabled) {
        const totalEntities = entities.length;
        for(let i = 0; i < totalEntities; i++) {
            const entity = entities[i];
            entity.enabled = enabled;
        }
    }

    isSeasonActive() {
        const now = new Date();
        const currentMonth = now.getMonth();
        const months = this.months;
        const totalMonths = months.length;
        for(let i = 0; i < totalMonths; i++) {
            const month = months[i];
            if(month - 1 === currentMonth)
                return true;
        }

        return false;
    }
}

pc.registerScript(SeasonalToggle, SeasonalToggle.name);

SeasonalToggle.attributes.add("months", {
    title: "Months",
    type: "number",
    array: true
});

SeasonalToggle.attributes.add("seasonalEntities", {
    title: "Seasonal Entities",
    type: "entity",
    array: true
});

SeasonalToggle.attributes.add("nonSeasonalEntities", {
    title: "Non-Seasonal Entities",
    type: "entity",
    array: true
});

// AspectRatioFitter.js
var AspectRatioFitter = pc.createScript('aspectRatioFitter');

AspectRatioFitter.attributes.add('fitMode', {
    type: 'number',
    enum: [
        { 'none': 0 },
        { 'contain parent': 1 },
        { 'cover parent': 2 },
        { 'width from parent height': 3 },
        { 'height from parent width': 4 },
    ],
    description: "Set how the element attached to this entity must be resized in order to preserve the target aspect ratio. " +
        "'None': nothing will be changed; " +
        "'Contain Parent': fit this element within the parent's bounding box; " +
        "'Cover Parent': fit this element to cover the entire parent's bounding box; " +
        "'Width from Parent Height': this element's width will be defined by the parent's height as 'w = parent.h * targetAspectRatio'; " +
        "'Height from Parent Width': this element's height will be defined by the parent's width as 'h = parent.w / targetAspectRatio'.",
    default: 0
});
AspectRatioFitter.attributes.add('targetAspectRatio', {
    type: "number",
    description: "The target aspect ratio to be maintained, defined as 'width / height'.",
    default: 1
});

AspectRatioFitter.prototype.initialize = function() {
    this._registerEvents('on');
    this.on('destroy', () => {
        this._registerEvents('off');
    }, this);
};

AspectRatioFitter.prototype.postInitialize = function() {
    this._recalculate();
};

AspectRatioFitter.prototype._registerEvents = function(onOrOff) {
    this.entity.element[onOrOff]('set:pivot', this._recalculate, this);
    this.entity.parent.element[onOrOff]('resize', this._recalculate, this);
    this.entity.parent.element[onOrOff]('set:pivot', this._recalculate, this);

    this[onOrOff]('attr:fitMode', this._recalculate, this);
    this[onOrOff]('attr:targetAspectRatio', this._recalculate, this);
};

AspectRatioFitter.prototype._recalculate = function() {
    if (this.fitMode === 0) {
        return;
    }

    const parentW = this.entity.parent.element.calculatedWidth;
    const parentH = this.entity.parent.element.calculatedHeight;
    const parentRatio = parentW / parentH;

    var w = parentW;
    var h = parentH;

    // check which coordinate must change in order to preserve the target aspect ratio
    if ((this.fitMode === 1 && parentRatio > this.targetAspectRatio) ||
        (this.fitMode === 2 && parentRatio < this.targetAspectRatio) ||
        (this.fitMode === 3)) {
        // use 'height' to re-calculate width
        w = h * this.targetAspectRatio;
    } else {
        // use 'width' to re-calculate height
        h = w / this.targetAspectRatio;
    }

    const splitAnchorsX = Math.abs(this.entity.element.anchor.x - this.entity.element.anchor.z) > 0.001;
    const splitAnchorsY = Math.abs(this.entity.element.anchor.y - this.entity.element.anchor.w) > 0.001;

    if (splitAnchorsX || splitAnchorsY) {
        this.entity.element.margin = new pc.Vec4(
            (parentW - w) * this.entity.element.pivot.x,
            (parentH - h) * this.entity.element.pivot.y,
            (parentW - w) * (1 - this.entity.element.pivot.x),
            (parentH - h) * (1 - this.entity.element.pivot.y)
        );
    }
    if (!splitAnchorsX) {
        this.entity.element.width = w;
    }
    if (!splitAnchorsY) {
        this.entity.element.height = h;
    }
};


// loading-screen.js
pc.script.createLoadingScreen(function (app) {
    var showSplash = function () {
        // splash wrapper
        var wrapper = document.createElement('div');
        wrapper.id = 'application-splash-wrapper';
        document.body.appendChild(wrapper);

        // splash
        var splash = document.createElement('div');
        splash.id = 'application-splash';
        wrapper.appendChild(splash);
        splash.style.display = 'none';

        var logo = document.createElement('img');
        logo.src = 'data:image/png;base64,';
        splash.appendChild(logo);
        logo.onload = function () {
            splash.style.display = 'block';
        };

        var container = document.createElement('div');
        container.id = 'progress-bar-container';
        splash.appendChild(container);

        var bar = document.createElement('div');
        bar.id = 'progress-bar';
        container.appendChild(bar);

    };

    var hideSplash = function () {
        var splash = document.getElementById('application-splash-wrapper');
        splash.parentElement.removeChild(splash);
    };

    var setProgress = function (value) {
        var bar = document.getElementById('progress-bar');
        if(bar) {
            value = Math.min(1, Math.max(0, value));
            bar.style.width = value * 100 + '%';
        }
    };

    var createCss = function () {
        var css = [
            'body {',
            '   background: rgb(15,15,15);',
            '   background: linear-gradient(0deg, rgba(15,15,15,1) 0%, rgba(35,46,48,1) 100%);',
            '}',
            '',
            '#application-splash-wrapper {',
            '    position: absolute;',
            '    top: 0;',
            '    left: 0;',
            '    height: 100%;',
            '    width: 100%;',
            '   background: rgb(15,15,15);',
            '   background: linear-gradient(0deg, rgba(15,15,15,1) 0%, rgba(35,46,48,1) 100%);',
            '}',
            '',
            '#application-splash {',
            '    position: absolute;',
            '    top: calc(50% - 40px);',
            '    width: 264px;',
            '    left: calc(50% - 132px);',
            '}',
            '',
            '#application-splash img {',
            '    width: 100%;',
            '}',
            '',
            '#progress-bar-container {',
            '    margin: 40px auto 0 auto;',
            '    height: 30px;',
            '    width: 100%;',
            '    border-radius:15px;',
            '    background-color: #414141;',
            '}',
            '',
            '#progress-bar {',
            '    width: 0%;',
            '    height: 100%;',
            '    border-radius:15px;',
            '    background-color: #aeaeae;',
            '}',
            '',
            '@media (max-width: 480px) {',
            '    #application-splash {',
            '        width: 170px;',
            '        left: calc(50% - 85px);',
            '    }',
            '}'
        ].join('\n');

        var style = document.createElement('style');
        style.type = 'text/css';
        if (style.styleSheet) {
            style.styleSheet.cssText = css;
        } else {
            style.appendChild(document.createTextNode(css));
        }

        document.head.appendChild(style);
    };

    createCss();
    showSplash();

    app.on('preload:end', function () {
        app.off('preload:progress');
    });
    app.on('preload:progress', setProgress);
    app.on('start', hideSplash);
});

// loading-screen-sc3.js
pc.script.createLoadingScreen(function (app) {
	var showSplash = function () {
		// splash wrapper
		var wrapper = document.createElement('div');
		wrapper.id = 'application-splash-wrapper';
		document.body.appendChild(wrapper);
		wrapper.setAttribute('draggable', false);
		wrapper.ondragstart = function (event) {
			event.preventDefault();
		};
		// splash
		var splash = document.createElement('div');
		splash.id = 'application-splash';
		wrapper.appendChild(splash);
		splash.style.display = 'none';
		splash.addEventListener('dragstart', function (event) {
			event.preventDefault();
		});

		var logo = document.createElement('img');
		logo.src = 'data:image/png;base64,';
		logo.setAttribute('draggable', false);
		logo.ondragstart = function (event) {
			event.preventDefault();
		};
		splash.appendChild(logo);
		logo.onload = function () {
			splash.style.display = 'block';
		};

		var spinner = document.createElement('div');
		spinner.id = 'loading-spinner';
		splash.appendChild(spinner);

		var container = document.createElement('div');
		container.id = 'progress-bar-container';
		wrapper.appendChild(container);

		var bar = document.createElement('div');
		bar.id = 'progress-bar';
		container.appendChild(bar);

		var percentage = document.createElement('div');
		percentage.id = 'progress-percentage';
		percentage.textContent = "0%";
		container.appendChild(percentage);
	};

	var hideSplash = function () {
		var splash = document.getElementById('application-splash-wrapper');
		if (splash) {
			splash.style.transition = 'opacity 0.5s ease'; // Add smooth fade transition
			splash.style.opacity = '0'; // Trigger fade-out

			// Remove the element after the transition completes
			setTimeout(function () {
				splash.parentElement.removeChild(splash);
			}, 500); // Match the duration of the transition
		}
	};
	var setProgress = function (value) {
		var bar = document.getElementById('progress-bar');
		var percentage = document.getElementById('progress-percentage');
		if (bar) {
			value = Math.min(1, Math.max(0, value));
			bar.style.width = value * 100 + '%';
			if (percentage) {
				percentage.textContent = Math.round(value * 100) + '%'; // Update the percentage text
			}
		}
	};

	var createCss = function () {
		var css = [
	`
	body {
	    margin: 0;
	    overflow: hidden;
	    height: 100%;
	}

	#application-splash-wrapper {
	    position: fixed;
	    top: 0;
	    left: 0;
	    height: 100%;
	    width: 100%;
		background-image: repeating-linear-gradient(45deg, transparent, transparent 100px, #2cb5ff 100px, #2cb5ff 200px);
		background-color: #40bcff;
	    display: flex; /* Flexbox to easily center items */
	    justify-content: center;
	    align-items: center;
	}
	
	#application-splash {
	    position: relative;
	    text-align: center;
	}

	#application-splash img {
	    display: block;
		pointer-events: none;
		user-select: none;
	    max-width: 100%;
	    max-height: 100%;
	    object-fit: cover;
	}

	#progress-bar-container {
	    position: fixed;
	    bottom: 75px;
	    left: 50%;
	    transform: translateX(-50%);
	    height: 30px;
	    width: 100%;
	    max-width: 480px;
	    border-radius: 10px;
	    background-color: #290000;
	    z-index: 2;
	}

	#progress-bar {
	    width: 0%;
	    height: 100%;
	    border-radius: 10px;
	    background-color:rgb(255, 227, 7);
    	filter: drop-shadow(5px 5px 10px rgba(0, 0, 0, 0.5));
	}

	#progress-percentage {
	    position: absolute;
	    top: 50%;
	    left: 50%;
	    transform: translate(-50%, -50%);
	    font-family: Tahoma, sans-serif;
	    font-size: 14px;
	    font-weight: bold;
	    color: #434343;
	    z-index: 3;
	}

	#loading-spinner {
	    position: absolute;
	    top: 50%;
	    left: 50%;
	    transform: translate(-50%, -50%);
	    width: 20px;
	    height: 20px;
	    border: 13px solid #353a3d;
	    border-top: 13px solid #6b6965;
	    border-radius: 50%;
	    animation: spin 1s linear infinite;
	}

	@keyframes spin {
	    0% {
	        transform: translate(-50%, -50%) rotate(0deg);
	    }
	    100% {
	        transform: translate(-50%, -50%) rotate(360deg);
	    }
	}

	@media (max-width: 480px) {
	    #progress-bar-container {
	        width: 200px; /* Adjust for smaller screens */
	    }
	}
	`
		];

		var style = document.createElement('style');
		style.type = 'text/css';
		if (style.styleSheet) {
			style.styleSheet.cssText = css;
		} else {
			style.appendChild(document.createTextNode(css));
		}

		document.head.appendChild(style);
	};

	createCss();
	showSplash();

	app.on('preload:end', function () {
		app.off('preload:progress');
	});
	app.on('preload:progress', setProgress);
	app.on('start', hideSplash);

});

// EntityRotatorV2.js
const EntityRotatorV2 = pc.createScript('EntityRotatorV2');

EntityRotatorV2.prototype.initialize = function() {
    this._tempQuat = new pc.Quat();
    this._tempEuler = new pc.Vec3();
};

EntityRotatorV2.prototype.update = function(dt) {
    // Calculate incremental rotation in degrees
    this._tempEuler.copy(this.degreesPerSecond);
    this._tempEuler.mulScalar(dt);

    // Convert incremental Euler to quaternion
    this._tempQuat.setFromEulerAngles(this._tempEuler.x, this._tempEuler.y, this._tempEuler.z);

    // Apply incremental local rotation
    this.entity.rotateLocal(this._tempEuler.x, this._tempEuler.y, this._tempEuler.z);
};

EntityRotatorV2.attributes.add("degreesPerSecond", {
    type: "vec3"
});


